// Encounter spaces, rewards and journal share the same persistent dungeon run.
const CITADEL_SOLIDS=[];
for(const room of [2,5]){const r=DUNGEON.rooms[room];for(const side of [-1,1])CITADEL_SOLIDS.push({room,type:'pillar',x:r.x+r.w/2+side*175-28,y:r.y+r.h/2-28,w:56,h:56})}
{const r=DUNGEON.rooms[3];for(const side of [-1,1])CITADEL_SOLIDS.push({room:3,type:'pool',x:r.x+r.w/2+(side<0?-240:65),y:r.y+r.h/2-75,w:175,h:150})}
{const r=DUNGEON.rooms[6];for(const side of [-1,1])CITADEL_SOLIDS.push({room:6,type:'barricade',x:r.x+r.w/2+side*200-70,y:r.y+r.h/2-24,w:140,h:48})}
const walkBeforeCitadel=dungeonWalkable;dungeonWalkable=function(x,y){return walkBeforeCitadel(x,y)&&!CITADEL_SOLIDS.some(r=>insideDungeonRect(x,y,r))};
function citadelFeatures(){if(!dungeonRun)return null;return dungeonRun.features||=( {chests:[],shrines:[],deaths:0,elapsed:0})}
function citadelFixtures(){const out=[];for(let n=1;n<=DUNGEON.combatCount;n++){const r=DUNGEON.rooms[n];out.push({type:'chest',room:n,x:r.x+r.w/2,y:r.y+r.h-145});if([2,5].includes(n))out.push({type:'shrine',room:n,x:r.x+170,y:r.y+r.h-270})}return out}
function useCitadelFixture(f){const state=citadelFeatures();if(!state||!f||p.area!=='forest'||Math.hypot(p.x-f.x,p.y-f.y)>92)return false;if(roomRemaining(f.room)>0||!dungeonRoomOpen(f.room)){toast('Önce bu odayı temizle.');return false}const list=f.type==='chest'?state.chests:state.shrines;if(list.includes(f.room)){toast(f.type==='chest'?'Bu sandık açıldı.':'Bu sunağın ışığı tükendi.');return false}list.push(f.room);
 if(f.type==='chest'){const gold=25+f.room*8;p.gold+=gold;state.goldEarned=(state.goldEarned||0)+gold;p.inventory.ore+=1+Math.floor(f.room/3);p.inventory.herb++;if([2,5].includes(f.room))p.inventory.energyPotion++;if([1,4].includes(f.room))p.potions++;toast('ODA SANDIĞI · +'+gold+' altın · Cevher ve erzak çantanda.');log(DUNGEON.rooms[f.room].name+' sandığı açıldı.')}else{p.hp=Math.min(p.maxHp,p.hp+Math.round(p.maxHp*.45));p.stamina=Math.min(100,p.stamina+50);toast('Soluk Sunağı · %45 can ve 50 enerji yenilendi.')}citadelBurst(f.x,f.y-25,f.type==='shrine'?'#b5d9c4':'#ead39a',22);ui();save();return true;
}
const interactBeforeCitadel=interact;interact=function(){if(p.area==='forest'&&dungeonRun&&!modalOpen()){const fixture=citadelFixtures().sort((a,b)=>Math.hypot(p.x-a.x,p.y-a.y)-Math.hypot(p.x-b.x,p.y-b.y))[0];if(fixture&&Math.hypot(p.x-fixture.x,p.y-fixture.y)<=92){useCitadelFixture(fixture);return}}interactBeforeCitadel()};
function drawCitadelFixture(f){const state=citadelFeatures(),ready=roomRemaining(f.room)===0&&dungeonRoomOpen(f.room),used=(f.type==='chest'?state.chests:state.shrines).includes(f.room),x=f.x,y=f.y;if(f.type==='chest'){shadow(x,y,27);rect(x-28,y-31,56,32,'#192533');rect(x-24,y-28,48,25,'#72563b');polygon([[x-28,y-32],[x-22,y-43],[x+22,y-43],[x+28,y-32]],used?'#3d3d37':'#927044');rect(x-22,y-39,44,4,'#c8ad72');for(const dx of [-18,13]){rect(x+dx,y-36,5,32,'#b09c6c');rect(x+dx+1,y-34,2,28,'#dfc98f')}rect(x-5,y-27,10,12,used?'#5c665d':'#ddc27c');if(ready&&!used){ctx.save();ctx.globalAlpha=.45+.15*Math.sin(time*4);ctx.strokeStyle='#dcc38a';ctx.lineWidth=2;ctx.strokeRect(x-32,y-47,64,49);ctx.restore()}}else{shadow(x,y,26);rect(x-30,y-7,60,10,'#4b6065');rect(x-22,y-18,44,11,'#8b9b90');rect(x-13,y-51,26,33,'#4f7474');polygon([[x,y-83],[x+13,y-65],[x+9,y-47],[x,y-40],[x-10,y-48],[x-14,y-65]],used?'#485c63':ready?'#a7ddc8':'#6a8c8b');rect(x-2,y-70,4,21,used?'#6e817d':'#edf2c5');if(ready&&!used){ctx.strokeStyle='#a9d4bc88';ctx.beginPath();ctx.ellipse(x,y,37,12,0,0,7);ctx.stroke()}}if(Math.hypot(p.x-x,p.y-y)<160)label(used?'TÜKENDİ':ready?'E · '+(f.type==='chest'?'Oda sandığı':'Soluk Sunağı'):'Odayı temizle',x,y-95,ready?'#e8d39b':'#a49d8c',11)}
function citadelDecorObjects(){const out=[];for(const r of CITADEL_SOLIDS){if(r.type==='pool')continue;out.push({y:r.y+r.h,draw:()=>{const x=r.x+r.w/2,y=r.y+r.h;if(r.type==='pillar'){shadow(x,y,38);rect(x-31,y-95,62,91,'#20313e');rect(x-25,y-88,50,80,'#536a70');rect(x-19,y-82,12,68,'#92a49b');rect(x+10,y-82,9,68,'#374f5b');rect(x-34,y-101,68,12,'#acb69e');rect(x-37,y-105,74,6,'#4f646b');rect(x-36,y-8,72,12,'#7e918c');rect(x-3,y-64,6,21,'#b1cabb')}else{rect(r.x,r.y,r.w,r.h,'#26343e');for(let n=0;n<5;n++){const xx=r.x+7+n*26;rect(xx,r.y-17-(n%2)*8,15,r.h+17,'#796a50');rect(xx+2,r.y-15-(n%2)*8,4,r.h+12,'#b49e73')}rect(r.x-4,r.y+8,r.w+8,7,'#3e5159')}}})}for(const f of citadelFixtures())out.push({y:f.y,draw:()=>drawCitadelFixture(f)});return out}
const furnitureBeforeCitadel=drawDungeonFurniture;drawDungeonFurniture=function(r,n){furnitureBeforeCitadel(r,n);for(const pool of CITADEL_SOLIDS.filter(q=>q.room===n&&q.type==='pool')){rect(pool.x-8,pool.y-8,pool.w+16,pool.h+16,'#1b3039');rect(pool.x,pool.y,pool.w,pool.h,'#244b4f');for(let i=0;i<7;i++)rect(pool.x+10+(i*29)%pool.w,pool.y+15+i*18,37,3,'#79a99355');rect(pool.x-8,pool.y+pool.h,pool.w+16,7,'#738d80');for(let i=0;i<4;i++){rect(pool.x+i*48,pool.y-16,8,16,'#91a18b');rect(pool.x+i*48,pool.y+pool.h,8,16,'#91a18b')}}
 if(n===4){const x=r.x+r.w/2,y=r.y+r.h/2;ctx.save();ctx.strokeStyle='#9e91804d';ctx.lineWidth=3;ctx.beginPath();ctx.arc(x,y,130,0,7);ctx.stroke();for(let j=0;j<8;j++){const a=j*Math.PI/4;rect(x+Math.cos(a)*133-4,y+Math.sin(a)*133-4,8,8,'#b49d6a66')}ctx.restore()}if(n===5){for(const side of [0,1]){const x=r.x+(side?r.w-80:80),y=r.y+320;rect(x-22,y,44,180,'#29333b');for(let shelf=0;shelf<4;shelf++){for(let book=0;book<5;book++)rect(x-17+book*7,y+8+shelf*44,5,27-book%3*4,['#997e5c','#6d8a83','#9d7674'][book%3]);rect(x-23,y+38+shelf*44,46,5,'#aa926c')}}}
};
let citadelAttackHeld=false,citadelAim=0;
canvas.addEventListener('pointermove',e=>{const r=canvas.getBoundingClientRect();citadelAim=Math.atan2((e.clientY-r.top)*VIEW.h/r.height+camera.y-p.y,(e.clientX-r.left)*VIEW.w/r.width+camera.x-p.x)});
canvas.addEventListener('pointerdown',e=>{if(e.button!==0||modalOpen())return;citadelAttackHeld=true;canvas.setPointerCapture?.(e.pointerId);attack()});canvas.addEventListener('pointerup',()=>citadelAttackHeld=false);canvas.addEventListener('pointercancel',()=>citadelAttackHeld=false);window.addEventListener('blur',()=>citadelAttackHeld=false);
const weaponBeforeAim=weaponAttack;weaponAttack=function(){weaponBeforeAim();if(citadelAttackHeld&&activeSwing){activeSwing.direction=citadelAim;attackAngle=citadelAim;p.facing=Math.abs(Math.cos(citadelAim))>.65?(Math.cos(citadelAim)>0?'right':'left'):(Math.sin(citadelAim)>0?'down':'up')}};
const tickBeforeHeldAttack=tickVigor;tickVigor=function(dt){tickBeforeHeldAttack(dt);if((keys[' ']||citadelAttackHeld)&&!modalOpen()&&!activeSwing&&!spinAction&&!dodgeAction&&cooldown<=0)attack()};
const readoutBeforeCitadel=updateDungeonReadout;updateDungeonReadout=function(){readoutBeforeCitadel();const boss=enemies.find(e=>e.boss&&!e.dead);if(boss){const phase=boss.combatPhase||1,action=boss.action?.type,title={cleave:'BALTA SAVURUŞU',slam:'ÇEKİRDEK ÇÖKÜŞÜ',chain:'ZİNCİR FIRLATMA',ring:'DIŞ HALKA · İÇERİ GİR'}[action];$('bossTarget').innerHTML=`<b>Kara Taş Gardiyanı · Nâzır</b><div><i style="width:${Math.max(0,boss.hp/boss.max*100)}%"></i></div><small>EVRE ${phase}/2 · ${Math.ceil(Math.max(0,boss.hp))} / ${boss.max}${title?' · '+title:''}</small>`}
 const enemy=enemies.filter(e=>!e.dead&&!e.boss&&dungeonRoomOpen(e.dungeonRoom)&&Math.hypot(p.x-e.x,p.y-e.y)<210).sort((a,b)=>Math.hypot(p.x-a.x,p.y-a.y)-Math.hypot(p.x-b.x,p.y-b.y))[0];$('enemyReadout').textContent=enemy?(enemy.elite?'♛ SEÇKİN · ':'')+CITADEL_ROLES[enemy.role].name+' · '+CITADEL_ROLES[enemy.role].hint:'';const fixture=citadelFixtures().find(f=>Math.hypot(p.x-f.x,p.y-f.y)<92);if(fixture)$('interactHint').textContent='E · '+(fixture.type==='chest'?'Oda sandığı':'Soluk Sunağı');
};
const defeatBeforeCitadelRewards=defeatEnemy;defeatEnemy=function(e){if(e.dead)return;const room=e.dungeonRoom,beforeGold=p.gold;defeatBeforeCitadelRewards(e);citadelBursts.push({type:'death',x:e.x,y:e.y,role:e.boss?'warden':e.role,color:'#c4b99c',life:.65,max:.65});if(e.elite){const gold=20+room*6;p.gold+=gold;particles.push({x:e.x,y:e.y-85,text:'SEÇKİN +'+gold+' ALTIN',color:'#f0d399',life:1.2});ui();save()}if(dungeonRun?.features){dungeonRun.features.goldEarned=(dungeonRun.features.goldEarned||0)+Math.max(0,p.gold-beforeGold);save()}if(!e.boss&&roomRemaining(room)===0&&enemies.some(q=>!q.boss&&!q.dead))toast(DUNGEON.rooms[room].name+' temizlendi · Sandığı aç, sonraki geçide ilerle.')};
const journalBeforeCitadel=renderJournal;renderJournal=function(){journalBeforeCitadel();const state=citadelFeatures();$('journalContracts').insertAdjacentHTML('beforeend',`<section class="citadel-run"><small>MAHZEN SEFERİ</small><h3>${dungeonRun?.complete?'Zafer kaydı':'Sefer günlüğü'}</h3><p>${Math.floor((state?.elapsed||0)/60)} dk ${Math.floor((state?.elapsed||0)%60)} sn · ${(state?.chests||[]).length}/6 sandık · ${(state?.shrines||[]).length}/2 sunak · ${state?.deaths||0} kurtarılma · ${state?.goldEarned||0} kazanılan altın</p><p class="fine">Space veya sol fare basılı: saldırı · Üçüncü vuruş: %130 hasar · F: 20 enerji ile kaçın · Q: Dönen Çelik.</p></section><h3>Mahzen yaratıkları</h3><div class="citadel-bestiary">${Object.entries(CITADEL_ROLES).map(([key,role])=>`<article><canvas data-citadel-codex="${key}" width="80" height="90" aria-label="${role.name}"></canvas><b>${role.name}</b><p>${role.hint}</p></article>`).join('')}<article class="citadel-boss-card"><canvas data-citadel-codex="warden" width="186" height="208" aria-label="Kara Taş Gardiyanı Nâzır"></canvas><div><b>Kara Taş Gardiyanı · Nâzır</b><p>Yakınında normal balta savuruşu yapar. Uzakta zincir fırlatır ve bulunduğun yere çekirdek darbesi indirir.</p><p>Canı yarıya düşünce ikinci evre başlar. Halka saldırısında dış çemberden kaç veya merkeze gir.</p><p>Turuncu alan: saldırı hazırlığı · F: kaçınma · Hücum sonrası açıklığı değerlendir.</p></div></article></div>`);$('journalContracts').querySelectorAll('[data-citadel-codex]').forEach(c=>{const g=c.getContext('2d'),sprite=citadelSprite(c.dataset.citadelCodex);g.imageSmoothingEnabled=false;g.drawImage(sprite,0,0,sprite.width,sprite.height,0,0,c.width,c.height)})};
const enterBeforeCitadelScene=enterForest;enterForest=function(){citadelAttackHeld=false;enterBeforeCitadelScene()};const returnBeforeCitadelScene=returnVillage;returnVillage=function(){citadelAttackHeld=false;$('enemyReadout').textContent='';returnBeforeCitadelScene()};
dungeonFloor=null;
